actions.script:
eventList = []
skippedCalendarIdList = []
const cf = ec.entity.conditionFactory
const levels = {CalpFreeBusy: 1, CalpView: 2, CalpEdit: 3, CalpManage: 4}
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
// start and end are days in the user's time zone (FullCalendar may add a time: only the day counts); a time
// stamp (epoch millis) is taken as its day
const pattern = 'yyyy-MM-dd HH:mm:ss.SSS'
const dayParameter = (value) => /^-?\d+$/.test(String(value)) ? ec.l10n.format(String(value), 'yyyy-MM-dd') : String(value).substring(0, 10)
const startText = dayParameter(start)
const endText = dayParameter(end)
const startTs = ec.l10n.parseTimestamp(startText + ' 00:00:00.000', pattern)
const endTs = ec.l10n.parseTimestamp(endText + ' 23:59:59.999', pattern)
if (startTs == null || endTs == null) { ec.message.addError(`The range ${start} to ${end} is not two days (yyyy-MM-dd)`); return }
const startDate = ec.l10n.parseDate(startText, 'yyyy-MM-dd')
const endDate = ec.l10n.parseDate(endText, 'yyyy-MM-dd')
const rangeStartMs = toMillis(startTs)

const addAll = (set, one, list) => {
    if (one && !set.includes(one)) set.push(one)
    if (list) for (const id of Array.from(list)) if (id && !set.includes(id)) set.push(id)
}
const facilityIdSet = []; addAll(facilityIdSet, facilityId, facilityIdList)
const partyIdSet = []; addAll(partyIdSet, partyId, partyIdList)
const assetIdSet = []; addAll(assetIdSet, assetId, assetIdList)
const userPartyId = ec.user.userAccount?.partyId || null
const calendarLevel = new Map()
const calendarOrder = []
if (publishToken) {
    const share = ec.entity.find('mantle.work.calendar.CalendarShare').condition('publishToken', String(publishToken))
            .condition(cf.makeConditionDate('fromDate', 'thruDate', null)).disableAuthz().one()
    const valid = share != null && !share.userId && !share.userGroupId && !share.partyId && (!share.passwordHash
            || (publishPassword && ec.user.passwordsMatch(String(publishPassword), share.passwordHash)))
    if (!valid) { ec.message.addError('This calendar link is not valid'); return }
    calendarLevel.set(share.calendarId, Math.min(levels[share.permissionEnumId] || 1, 2))
    calendarOrder.push(share.calendarId)
    facilityIdSet.length = 0; partyIdSet.length = 0; assetIdSet.length = 0
} else if (calendarIdList != null) {
    const asked = []; addAll(asked, null, calendarIdList)
    if (asked.length) {
        const access = ec.service.sync().name('mantle.work.CalendarServices.check#CalendarAccess').parameters({calendarIdList: asked}).call()
        if (ec.message.hasError()) return
        for (const id of asked) {
            const level = levels[access.permissionMap?.[id]] || 0
            if (level) { calendarLevel.set(id, level); calendarOrder.push(id) } else skippedCalendarIdList.push(id)
        }
        if (skippedCalendarIdList.length) ec.logger.info(`Calendars not shown, not found or not shared with ${ec.user.username}: ${skippedCalendarIdList.join(', ')}`)
    }
    if (!partyIdSet.length && userPartyId) partyIdSet.push(userPartyId)
}
// a project's calendar: only its linked events, all of them for a party of the project, else the user's own
let projectEventIds = []
let linkedIds = null
if (rootWorkEffortId && !publishToken) {
    linkedIds = Array.from(ec.entity.find('mantle.work.effort.WorkEffortRecord').condition('recordEntityName', 'mantle.work.effort.WorkEffort')
            .condition('recordId', rootWorkEffortId).selectField('workEffortId').list()).map((row) => row.workEffortId)
    if (!linkedIds.length) return
    const onProject = ec.user.isInGroup('ADMIN') || (!!userPartyId && ec.entity.find('mantle.work.effort.WorkEffortParty')
            .condition('workEffortId', rootWorkEffortId).condition('partyId', userPartyId).condition(cf.makeConditionDate('fromDate', 'thruDate', null)).count() > 0)
    if (onProject) projectEventIds = linkedIds
    else if (userPartyId && !partyIdSet.includes(userPartyId)) partyIdSet.push(userPartyId)
}
if (!facilityIdSet.length && !partyIdSet.length && !assetIdSet.length && !calendarLevel.size && !projectEventIds.length) return
const calendarRows = new Map()
if (calendarLevel.size) for (const row of ec.entity.find('mantle.work.calendar.Calendar')
        .condition(cf.makeCondition('calendarId', 'in', Array.from(calendarLevel.keys()))).disableAuthz().list()) calendarRows.set(row.calendarId, row)

// an event overlaps the range: a timed one by its estimated or actual dates (one without an end when it starts
// after the day before the range), an all-day one by its days, a cron series from its start to recurEndDate
const types = workEffortTypeEnumIds && Array.from(workEffortTypeEnumIds).length ? Array.from(workEffortTypeEnumIds) : ['WetEvent']
const typeConditions = [cf.makeCondition('workEffortTypeEnumId', 'in', types)]
if (excludeCancelled) typeConditions.push(cf.makeCondition('statusId', 'not-equals', 'WeCancelled', true))
if (linkedIds) typeConditions.push(cf.makeCondition('workEffortId', 'in', linkedIds.slice(0, 1000)))
const typeCondition = cf.makeCondition(typeConditions, 'and')
const dayBeforeStart = new Date(rangeStartMs - 86400000)
const recurEndOk = cf.makeCondition([cf.makeCondition('recurEndDate', 'is-null', null),
    cf.makeCondition('recurEndDate', 'greater-equals', startTs)], 'or')
const timed = (startField, endField) => cf.makeCondition([
    cf.makeCondition(startField, 'less-equals', endTs),
    cf.makeCondition([
        cf.makeCondition(endField, 'greater-equals', startTs),
        cf.makeCondition([cf.makeCondition(endField, 'is-null', null), cf.makeCondition(startField, 'greater-equals', dayBeforeStart)], 'and'),
        cf.makeCondition('recurStartCron', 'is-not-null', null)], 'or'),
    recurEndOk], 'and')
const allDay = cf.makeCondition([
    cf.makeCondition('allDayStart', 'less-equals', endDate),
    cf.makeCondition([
        cf.makeCondition('allDayEnd', 'greater-equals', startDate),
        cf.makeCondition([cf.makeCondition('allDayEnd', 'is-null', null), cf.makeCondition('allDayStart', 'greater-equals', startDate)], 'and'),
        cf.makeCondition('recurStartCron', 'is-not-null', null)], 'or'),
    recurEndOk], 'and')
const dateCondition = cf.makeCondition([timed('estimatedStartDate', 'estimatedCompletionDate'),
    timed('actualStartDate', 'actualCompletionDate'), allDay], 'or')

// why each event is in
const members = new Map()
const memberOf = (id) => {
    let member = members.get(id)
    if (!member) {
        member = {calendarIds: [], partyRows: [], owner: false, allUsers: false, resource: false, project: false, bookingStatusId: null}
        members.set(id, member)
    }
    return member
}
const personal = partyIdSet.length > 0 || calendarLevel.size > 0
const collect = (base) => {
    const direct = []
    if (includeAllUsers && personal && !publishToken) direct.push(cf.makeCondition('visibilityEnumId', 'equals', 'WevAllUsers'))
    if (partyIdSet.length) direct.push(cf.makeCondition('ownerPartyId', 'in', partyIdSet))
    if (facilityIdSet.length) direct.push(cf.makeCondition('facilityId', 'in', facilityIdSet))
    if (direct.length) for (const row of ec.entity.find('mantle.work.effort.WorkEffort').condition(base)
            .condition(cf.makeCondition(direct, 'or')).selectField('workEffortId,visibilityEnumId,ownerPartyId,facilityId').list()) {
        const member = memberOf(row.workEffortId)
        if (row.visibilityEnumId === 'WevAllUsers') member.allUsers = true
        if (row.ownerPartyId && partyIdSet.includes(row.ownerPartyId)) member.owner = true
        if (row.facilityId && facilityIdSet.includes(row.facilityId)) member.resource = true
    }
    if (partyIdSet.length) for (const row of ec.entity.find('mantle.work.effort.WorkEffortAndParty').condition(base)
            .condition(cf.makeCondition('partyId', 'in', partyIdSet)).condition(cf.makeConditionDate('fromDate', 'thruDate', null))
            .selectField('workEffortId,partyId,roleTypeId,partyStatusId,availabilityEnumId').list()) {
        memberOf(row.workEffortId).partyRows.push({partyId: row.partyId, roleTypeId: row.roleTypeId, statusId: row.partyStatusId ?? null,
            availabilityEnumId: row.availabilityEnumId ?? null})
    }
    if (facilityIdSet.length) for (const row of ec.entity.find('mantle.work.effort.WorkEffortAndFacilityBooking').condition(base)
            .condition(cf.makeCondition('facilityId', 'in', facilityIdSet))
            .condition(cf.makeCondition('bookingStatusId', 'not-equals', 'WefRequestDenied', true))
            .selectField('workEffortId,facilityId,bookingStatusId').list()) {
        const member = memberOf(row.workEffortId)
        member.resource = true
        if (row.bookingStatusId && !member.bookingStatusId) member.bookingStatusId = row.bookingStatusId
    }
    if (assetIdSet.length) for (const row of ec.entity.find('mantle.work.effort.WorkEffortAndAssetBooking').condition(base)
            .condition(cf.makeCondition('assetId', 'in', assetIdSet))
            .condition(cf.makeCondition('bookingStatusId', 'not-equals', 'WeaaRequestDenied', true))
            .selectField('workEffortId,assetId,bookingStatusId,bookingThruDate,actualStartDate,estimatedStartDate').list()) {
        // an assignment that ended before the event started was cancelled (cancel#ResourceBooking)
        const thru = toMillis(row.bookingThruDate)
        const eventStart = toMillis(row.actualStartDate || row.estimatedStartDate)
        if (thru != null && (eventStart == null ? thru <= toMillis(ec.user.nowTimestamp) : thru <= eventStart)) continue
        const member = memberOf(row.workEffortId)
        member.resource = true
        if (row.bookingStatusId && !member.bookingStatusId) member.bookingStatusId = row.bookingStatusId
    }
    if (projectEventIds.length) for (let i = 0; i < projectEventIds.length; i += 500) for (const row of ec.entity.find('mantle.work.effort.WorkEffort').condition(base)
            .condition(cf.makeCondition('workEffortId', 'in', projectEventIds.slice(i, i + 500))).selectField('workEffortId').list()) memberOf(row.workEffortId).project = true
    if (calendarLevel.size) for (const row of ec.entity.find('mantle.work.calendar.CalendarWorkEffortDetail').condition(base)
            .condition(cf.makeCondition('calendarId', 'in', Array.from(calendarLevel.keys()))).selectField('workEffortId,calendarId').list()) {
        const member = memberOf(row.workEffortId)
        if (!member.calendarIds.includes(row.calendarId)) member.calendarIds.push(row.calendarId)
    }
}
collect(cf.makeCondition([typeCondition, dateCondition], 'and'))
// a series (WorkEffortRecurrence) that started before the range may have instances in it
const seriesIds = Array.from(ec.entity.find('mantle.work.effort.WorkEffortAndRecurrence').condition(typeCondition)
        .condition(cf.makeCondition([cf.makeCondition('estimatedStartDate', 'less-equals', endTs),
            cf.makeCondition('actualStartDate', 'less-equals', endTs), cf.makeCondition('allDayStart', 'less-equals', endDate)], 'or'))
        .selectField('workEffortId').list()).map((row) => row.workEffortId).filter((id) => !members.has(id))
if (seriesIds.length) collect(cf.makeCondition([typeCondition, cf.makeCondition('workEffortId', 'in', seriesIds)], 'and'))

const isDeclined = (row) => row.statusId === 'WeptDeclined' || row.statusId === 'WeptUnassigned'
const owners = new Map()
if (members.size) for (const row of ec.entity.find('mantle.work.effort.WorkEffort').condition(cf.makeCondition('workEffortId', 'in',
        Array.from(members.keys()))).selectField('workEffortId,ownerPartyId').list()) owners.set(row.workEffortId, row.ownerPartyId ?? null)
const shownIds = []
for (const [id, member] of members) {
    const declined = member.partyRows.length > 0 && !member.owner && !member.calendarIds.length && !member.resource && !member.project
            && member.partyRows.every(isDeclined)
    // the user's own declined invitation, whatever calendar it is in
    const mine = userPartyId ? member.partyRows.filter((row) => row.partyId === userPartyId) : []
    const declinedByUser = mine.length > 0 && mine.every(isDeclined) && owners.get(id) !== userPartyId && !member.resource
    if ((declined || declinedByUser) && !showDeclined) continue
    shownIds.push(id)
}
if (!shownIds.length) return
const rows = Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition(cf.makeCondition('workEffortId', 'in', shownIds)).list())
const instances = ec.service.sync().name('mantle.work.EventServices.get#EventInstances').parameters({
    workEffortList: rows.map((row) => row.getMap()), rangeStart: startTs, rangeEnd: endTs}).call()?.instanceList || []
if (ec.message.hasError()) return

const purposeNames = new Map()
const purposeOf = (enumId) => {
    if (!enumId) return null
    if (!purposeNames.has(enumId)) purposeNames.set(enumId, ec.entity.find('moqui.basic.Enumeration').condition('enumId', enumId)
            .useCache(true).one()?.description || null)
    return purposeNames.get(enumId)
}
const titleOf = (workEffort) => {
    try {
        return ec.resource.expand(titleGString, '', {workEffort: workEffort})
    } catch (err) {
        return `${workEffort.workEffortName || purposeOf(workEffort.purposeEnumId) || 'Event'} [${workEffort.workEffortId}]`
    }
}
const timedFormat = "yyyy-MM-dd'T'HH:mm:ss"
const formatOf = (millis) => millis == null ? null : ec.l10n.format(String(millis), timedFormat)
// the organizers' names, as the user's filters show the parties
const ownerNames = new Map()
const ownerIds = Array.from(new Set(instances.map((instance) => instance.workEffort?.ownerPartyId).filter((id) => id)))
if (ownerIds.length) for (const detail of ec.entity.find('mantle.party.PartyDetail').condition(cf.makeCondition('partyId', 'in', ownerIds)).list())
    ownerNames.set(detail.partyId, detail.organizationName || [detail.firstName, detail.lastName].filter((part) => part).join(' ') || detail.partyId)
for (const instance of instances) {
    const workEffort = instance.workEffort
    const member = members.get(instance.workEffortId) || members.get(instance.seriesWorkEffortId) || memberOf(instance.workEffortId)
    const calendarId = calendarOrder.find((id) => member.calendarIds.includes(id)) || null
    const freeBusyOnly = member.calendarIds.length > 0 && member.calendarIds.every((id) => calendarLevel.get(id) === 1)
            && !member.partyRows.length && !member.owner && !member.allUsers && !member.resource && !member.project
    const partyRow = member.partyRows.find((row) => row.partyId === userPartyId) || member.partyRows[0] || null
    let url = ''
    if (urlGString && !freeBusyOnly) {
        try { url = ec.resource.expand(urlGString, '', {workEffort: workEffort}) } catch (err) { url = '' }
    }
    eventList.push({id: instance.workEffortId, title: freeBusyOnly ? 'Busy' : titleOf(workEffort),
        start: instance.allDay ? instance.startDay : formatOf(instance.start),
        end: instance.allDay ? instance.endDay : formatOf(instance.end), allDay: !!instance.allDay, url: url,
        workEffortId: instance.workEffortId, workEffortTypeEnumId: workEffort.workEffortTypeEnumId ?? null,
        statusId: workEffort.statusId ?? null, calendarId: calendarId, color: calendarId ? (calendarRows.get(calendarId)?.color ?? null) : null,
        partyStatusId: partyRow?.statusId ?? null, availabilityEnumId: partyRow?.availabilityEnumId ?? null,
        bookingStatusId: member.bookingStatusId, recurring: !!instance.recurring, recurringEventId: instance.seriesWorkEffortId ?? null,
        instanceStart: instance.recurrenceStart == null ? null : (instance.allDay ? ec.l10n.format(String(instance.recurrenceStart), 'yyyy-MM-dd')
            : formatOf(instance.recurrenceStart)),
        startMillis: instance.start, endMillis: instance.end ?? null, freeBusyOnly: freeBusyOnly,
        location: freeBusyOnly ? null : (workEffort.location ?? null), ownerPartyId: freeBusyOnly ? null : (workEffort.ownerPartyId ?? null),
        ownerName: freeBusyOnly || !workEffort.ownerPartyId ? null : (ownerNames.get(workEffort.ownerPartyId) ?? null)})
}
eventList.sort((a, b) => a.startMillis - b.startMillis || String(a.title).localeCompare(String(b.title)))

instanceList = []
toolMissing = false
const cf = ec.entity.conditionFactory
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const text = String(value)
    if (/^-?\d+$/.test(text)) return Number(text)
    const parsed = Date.parse(text)
    return Number.isNaN(parsed) ? null : parsed
}
const rangeStartMs = toMillis(rangeStart)
const rangeEndMs = toMillis(rangeEnd)
const pattern = 'yyyy-MM-dd HH:mm:ss.SSS'
const dayText = (millis) => ec.l10n.format(String(millis), 'yyyy-MM-dd')
const dayStartMs = (text) => toMillis(ec.l10n.parseTimestamp(text + ' 00:00:00.000', pattern))
// a date field has no time zone: it reaches a script as yyyy-MM-dd text or the epoch millis of its UTC midnight
const dayTextOf = (value) => {
    if (value == null || value === '') return null
    const text = String(value)
    if (/^\d{4}-\d{2}-\d{2}/.test(text)) return text.substring(0, 10)
    const millis = toMillis(value)
    return millis == null ? null : new Date(millis).toISOString().substring(0, 10)
}
const addDays = (text, days) => {
    const [y, m, d] = text.split('-').map(Number)
    return new Date(Date.UTC(y, m - 1, d + days)).toISOString().substring(0, 10)
}
const utcDayStart = (millis) => { const at = new Date(millis); return Date.UTC(at.getUTCFullYear(), at.getUTCMonth(), at.getUTCDate()) }
const unitMillis = {TF_ms: 1, TF_s: 1000, TF_min: 60000, TF_hr: 3600000, TF_day: 86400000, TF_wk: 604800000}
const spanOf = (workEffort) => {
    const startMs = toMillis(workEffort.actualStartDate || workEffort.estimatedStartDate)
    if (startMs == null) {
        const startDay = dayTextOf(workEffort.allDayStart)
        if (!startDay) return null
        const lastDay = dayTextOf(workEffort.allDayEnd) || startDay
        const endDay = addDays(lastDay < startDay ? startDay : lastDay, 1)
        return {startMs: dayStartMs(startDay), endMs: dayStartMs(endDay), allDay: true}
    }
    let endMs = toMillis(workEffort.actualCompletionDate || workEffort.estimatedCompletionDate)
    if (endMs == null) {
        const amount = [workEffort.actualWorkDuration, workEffort.estimatedWorkDuration, workEffort.estimatedWorkTime]
                .map((value) => value == null ? null : Number(String(value))).find((value) => value != null && !Number.isNaN(value) && value !== 0)
        if (amount != null) endMs = startMs + Math.round(amount * (unitMillis[workEffort.timeUomId || 'TF_hr'] || 3600000))
    }
    return {startMs: startMs, endMs: endMs, allDay: false}
}
const push = (workEffort, startMs, span, extra) => {
    const duration = span.endMs != null ? span.endMs - span.startMs : null
    const endMs = duration != null ? startMs + duration : null
    if (startMs > rangeEndMs) return
    if (endMs != null ? endMs <= rangeStartMs : startMs < rangeStartMs) return
    let startDay = null
    let endDay = null
    if (span.allDay) {
        startDay = dayText(startMs)
        endDay = addDays(startDay, Math.max(1, Math.round((duration || 86400000) / 86400000)))
    }
    instanceList.push(Object.assign({workEffortId: workEffort.workEffortId, start: startMs, end: endMs, allDay: span.allDay,
        startDay: startDay, endDay: endDay, recurring: false, seriesWorkEffortId: null, recurrenceStart: null,
        workEffort: workEffort}, extra || {}))
}

const list = Array.from(workEffortList || []).filter((row) => row && row.workEffortId)
const ids = list.map((row) => row.workEffortId)
const inputById = new Map(list.map((row) => [row.workEffortId, row]))
if (!ids.length) return
const recurrences = new Map(Array.from(ec.entity.find('mantle.work.effort.WorkEffortRecurrence')
        .condition(cf.makeCondition('workEffortId', 'in', ids)).list()).map((row) => [row.workEffortId, row]))
const seriesIds = ids.filter((id) => recurrences.get(id)?.rrule)
// the instances changed on their own: of the series asked for, and those asked for themselves
const links = Array.from(ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('workEffortAssocTypeEnumId', 'WeatRecurrenceInstance')
        .condition(cf.makeCondition(seriesIds.length ? [cf.makeCondition('workEffortId', 'in', seriesIds),
            cf.makeCondition('toWorkEffortId', 'in', ids)] : [cf.makeCondition('toWorkEffortId', 'in', ids)], 'or')).list())
const overrides = new Map()
for (const link of links) if (!overrides.has(link.toWorkEffortId)) overrides.set(link.toWorkEffortId,
        {seriesId: link.workEffortId, recurrenceStart: toMillis(link.fromDate)})
const replacedBySeries = new Map()
for (const [, override] of overrides) {
    if (!replacedBySeries.has(override.seriesId)) replacedBySeries.set(override.seriesId, new Set())
    replacedBySeries.get(override.seriesId).add(override.recurrenceStart)
}

let tool
const toolOf = () => {
    if (tool === undefined) tool = ec.factory.getToolFactory('ICalendar') != null ? ec.factory.getTool('ICalendar') : null
    return tool
}
const splitValues = (text) => text ? String(text).split(/[,\s]+/).filter((part) => part) : []
for (const workEffort of list) {
    const id = workEffort.workEffortId
    if (overrides.has(id)) continue
    const span = spanOf(workEffort)
    if (span == null) continue
    const recurrence = recurrences.get(id)
    if (recurrence?.rrule) {
        const duration = span.endMs != null ? span.endMs - span.startMs : 0
        let starts = null
        const expander = toolOf()
        if (expander) {
            try {
                starts = Array.from(expander.expand(String(recurrence.rrule), span.startMs, recurrence.timeZone || ec.user.timeZone || null,
                        splitValues(recurrence.exdates), splitValues(recurrence.rdates), rangeStartMs - duration, rangeEndMs) || [])
                        .map(toMillis).filter((value) => value != null)
            } catch (err) {
                ec.logger.error(`Recurrence of ${id} (${recurrence.rrule}) not expanded: ${err && err.message ? err.message : err}`)
            }
        } else {
            toolMissing = true
        }
        if (starts == null) starts = [span.startMs]
        const replaced = replacedBySeries.get(id) || new Set()
        for (const startMs of starts) if (!replaced.has(startMs))
            push(workEffort, startMs, span, {recurring: true, seriesWorkEffortId: id, recurrenceStart: startMs})
    } else if (workEffort.recurStartCron) {
        const cron = String(workEffort.recurStartCron)
        const duration = span.endMs != null ? span.endMs - span.startMs : 0
        const eventStartDayMs = utcDayStart(span.startMs)
        const limit = workEffort.recurLimit != null && Number(String(workEffort.recurLimit)) > 0 ? Number(String(workEffort.recurLimit)) : null
        const recurEndMs = toMillis(workEffort.recurEndDate)
        // with a limit the instances are counted from the start, else only those of the range are looked at
        let next = limit != null ? eventStartDayMs : Math.max(eventStartDayMs, rangeStartMs - duration - 1)
        let count = 0
        for (let guard = 0; guard < 100000; guard++) {
            const fire = ec.service.nextCronExecution(cron, next)
            if (fire == null) break
            next = Number(fire)
            if (next > rangeEndMs) break
            if (recurEndMs != null && next > recurEndMs) break
            if (next <= eventStartDayMs) continue
            count++
            if (limit != null && count > limit) break
            push(workEffort, next, span, {recurring: true, seriesWorkEffortId: id, recurrenceStart: next})
        }
    } else {
        push(workEffort, span.startMs, span)
    }
}
if (toolMissing) {
    let logged = false
    try {
        const notices = ec.cache.getCache('mantle.work.calendar.notices')
        logged = !!notices.get('expandNoTool')
        if (!logged) notices.put('expandNoTool', true)
    } catch (err) { logged = false }
    if (!logged) ec.logger.info('Recurring events show their first instance only: the framework ICalendar tool is not available to expand RRULEs')
}
// the changed instances, with their own dates, in place of the generated ones
const missing = Array.from(overrides.keys()).filter((id) => !inputById.has(id))
const fetched = missing.length ? new Map(Array.from(ec.entity.find('mantle.work.effort.WorkEffort')
