                    dayNumber(dayTextOf(series.allDayEnd)) - dayNumber(dayTextOf(series.allDayStart))) : null}
                : {estimatedStartDate: new Date(keyMs), estimatedCompletionDate: new Date(keyMs + (toMillis(series.estimatedCompletionDate) != null
                    ? toMillis(series.estimatedCompletionDate) - seriesStartMs : 3600000))}
            const nextId = newWorkEffort(series.getMap(), Object.assign({}, instanceBase, fields, {universalId: null}))
            const nextParts = shiftRule(parts.filter(([key]) => key !== 'COUNT' && key !== 'UNTIL'), dayDelta)
                    .concat(countLeft != null ? [['COUNT', String(countLeft)]] : (parts.find(([key]) => key === 'UNTIL') ? [parts.find(([key]) => key === 'UNTIL')] : []))
            call('create#mantle.work.effort.WorkEffortRecurrence', {workEffortId: nextId, rrule: ruleText(nextParts),
                exdates: recurrence.exdates || null, rdates: null, timeZone: recurrence.timeZone || ec.user.timeZone || null})
            copyRows(series.workEffortId, nextId, true)
            // the instances changed after it go with the new series
