                const oldKey = toMillis(assoc.fromDate)
                if (oldKey >= keyMs) relink(assoc.toWorkEffortId, series.workEffortId, nextId, oldKey + deltaMs)
            }
            splitSeriesId = series.workEffortId
            targetWorkEffortId = nextId
            seriesWorkEffortId = nextId
        }
    }
    if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
} catch (err) {
    if (!ec.message.hasError()) ec.message.addError(String(err && err.message ? err.message : err))
