            for (const userId of Array.from(nm.getNotifyUserIds() ?? [])) if (!notifiedUserIds.includes(userId)) notifiedUserIds.push(userId)
            sent = true
        } else {
            const toAddress = ec.service.sync().name('mantle.party.ContactServices.get#PrimaryEmailAddress').parameters({partyId: partyId}).call()?.emailAddress
            if (!toAddress) { skippedList.push({partyId: partyId, reason: 'no user account and no email address'}); continue }
            if (!fromAddressOf()) { skippedList.push({partyId: partyId, reason: 'no email address of the organizer to send from'}); continue }
            const verb = cancelled ? 'Cancelled' : (sentBefore ? 'Updated invitation' : 'Invitation')
            const subject = `${verb}: ${event.workEffortName || workEffortId} (${whenText})`
            const what = removal ? 'removed you from' : (cancelled ? 'cancelled' : (sentBefore ? 'updated' : 'invited you to'))
            const lines = [`${organizerName} ${what} ${event.workEffortName || workEffortId}`,
                `When: ${whenText}`].concat(whereText ? [`Where: ${whereText}`] : [], message ? ['', String(message)] : [],
                event.description && !removal ? ['', String(event.description)] : [])
            const attachment = icsOf(toAddress)
            ec.service.sync().name('org.moqui.impl.EmailServices.send#EmailTemplate').parameters({
                emailTemplateId: 'MANTLE_CALENDAR_EMAIL', toAddresses: toAddress,
                bodyParameters: {subject: subject, fromAddress: fromAddressOf(), fromName: organizerName},
                body: '<html><body>' + lines.map((line) => line ? `<p>${escape(line)}</p>` : '').join('') + '</body></html>',
                bodyText: lines.join('\n'),
                attachments: attachment ? [{fileName: 'invite.ics', contentType: `text/calendar; method=${method}; charset=UTF-8`,
                    contentText: attachment}] : null}).call()
            if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
            if (!emailedAddressList.includes(toAddress)) emailedAddressList.push(toAddress)
            if (attachment) icsTextMap[partyId] = attachment
            sent = true
        }
        if (sent) {
            if (!removal) for (const row of rows) { row.set('invitationSentDate', now); row.set('invitationDigest', digest); row.update() }
            sentPartyIdList.push(partyId)
        }
    } catch (err) {
        const reason = String(err && err.message ? err.message : err)
        ec.logger.error(`Invitation to ${workEffortId} for party ${partyId} not sent: ${reason}`)
        skippedList.push({partyId: partyId, reason: reason})
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}

removedCount = 0; notified = false; notifiedUserIds = []; emailedAddressList = []; cancelIcsText = null
const access = ec.service.sync().name('mantle.work.EventServices.check#EventAccess').parameters({workEffortId: workEffortId, permission: 'edit'}).call()
if (ec.message.hasError()) return
if (access.workEffort?.ownerPartyId === partyId) { ec.message.addError('The organizer stays on the event'); return }
const cf = ec.entity.conditionFactory
const rows = Array.from(ec.entity.find('mantle.work.effort.WorkEffortParty').condition('workEffortId', workEffortId)
        .condition('partyId', partyId).condition(cf.makeConditionDate('fromDate', 'thruDate', null)).list())
if (!rows.length) return
if (notify && rows.some((row) => row.invitationSentDate != null)) {
    ec.message.pushErrors()
    try {
        const sent = ec.service.sync().name('mantle.work.EventServices.send#EventInvitations').parameters({workEffortId: workEffortId,
            partyIdList: [partyId], attendeeRemoved: true, message: message || null, eventUrl: eventUrl || null}).call()
