    } catch (err) {
        ec.logger.error(`Event ${workEffortId}: the cancel to removed party ${partyId} was not sent: ${err && err.message ? err.message : err}`)
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
    }
}
const now = ec.user.nowTimestamp
for (const row of rows) { row.set('thruDate', now); row.update(); removedCount++ }

freeBusyList = []
suggestedSlotList = []
const cf = ec.entity.conditionFactory
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const text = String(value)
    return /^-?\d+$/.test(text) ? Number(text) : Date.parse(text)
}
const fromMs = toMillis(fromDate)
const thruMs = toMillis(thruDate)
if (!(thruMs > fromMs)) { ec.message.addError('Free/busy needs thruDate after fromDate'); return }
if (thruMs - fromMs > 92 * 86400000) { ec.message.addError('Free/busy covers at most 92 days'); return }
const dayText = (millis) => ec.l10n.format(String(millis), 'yyyy-MM-dd')
const unique = (list) => Array.from(new Set(Array.from(list || []).filter((id) => id)))
const intervalsOf = (params, statusOf) => {
    const out = ec.service.sync().name('mantle.work.EventServices.get#FullCalendarData').parameters(Object.assign({
        start: dayText(fromMs), end: dayText(thruMs), includeAllUsers: false, excludeCancelled: true, titleGString: '-'}, params)).call()
    if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    const intervals = []
    for (const event of Array.from(out?.eventList || [])) {
        if (excludeWorkEffortId && (event.workEffortId === excludeWorkEffortId || event.recurringEventId === excludeWorkEffortId)) continue
        const status = statusOf ? statusOf(event) : 'busy'
        if (!status) continue
        const startMs = toMillis(event.startMillis)
        // an event without an end is taken as an hour long
        const endMs = event.endMillis != null ? toMillis(event.endMillis) : startMs + 3600000
        if (endMs <= fromMs || startMs >= thruMs) continue
        intervals.push({fromMs: Math.max(startMs, fromMs), thruMs: Math.min(endMs, thruMs), status: status})
    }
    return intervals.sort((a, b) => a.fromMs - b.fromMs)
}
const asDates = (intervals) => intervals.map((interval) => Object.assign({fromDate: new Date(interval.fromMs), thruDate: new Date(interval.thruMs)},
        interval.status ? {status: interval.status} : {}))
const partyStatus = (event) => {
    if (event.availabilityEnumId === 'WeptaAvailable') return null
    if (event.workEffortTypeEnumId === 'WetTimeOff') return 'away'
    if (event.partyStatusId === 'WeptOffered' || event.partyStatusId === 'WeptTentative') return 'tentative'
    return 'busy'
}
const bookingStatus = (event) => event.bookingStatusId === 'WefRequested' || event.bookingStatusId === 'WeaaRequested' ? 'requested' : 'busy'
// working hours: 09:00 to 17:00, Monday to Friday, by the user's days
const defaultHours = () => {
    const hours = []
    const pattern = 'yyyy-MM-dd HH:mm:ss.SSS'
    let day = dayText(fromMs)
    const lastDay = dayText(thruMs)
    for (let guard = 0; guard < 100 && day <= lastDay; guard++) {
        const [y, m, d] = day.split('-').map(Number)
        const weekday = new Date(Date.UTC(y, m - 1, d)).getUTCDay()
        if (weekday >= 1 && weekday <= 5) {
            const start = toMillis(ec.l10n.parseTimestamp(day + ' 09:00:00.000', pattern))
            const end = toMillis(ec.l10n.parseTimestamp(day + ' 17:00:00.000', pattern))
            if (end > fromMs && start < thruMs) hours.push({fromMs: Math.max(start, fromMs), thruMs: Math.min(end, thruMs)})
        }
        day = new Date(Date.UTC(y, m - 1, d + 1)).toISOString().substring(0, 10)
    }
    return hours
}
const busyAll = []
const hoursByParty = []
const failed = []
const attempt = (label, run) => {
    ec.message.pushErrors()
    try { run() } catch (err) {
        const reason = String(err && err.message ? err.message : err)
        ec.logger.error(`Free/busy of ${label} not read: ${reason}`)
        failed.push(label)
    } finally { ec.message.clearErrors(); ec.message.popErrors() }
}
for (const partyId of unique(partyIdList)) attempt(`party ${partyId}`, () => {
    const busy = intervalsOf({partyId: partyId, workEffortTypeEnumIds: ['WetEvent', 'WetTimeOff']}, partyStatus)
    const entry = {resourceType: 'party', partyId: partyId, busyList: asDates(busy), workingHourList: null}
    const hasAvailable = ec.entity.find('mantle.work.effort.WorkEffortAndParty').condition('workEffortTypeEnumId', 'WetAvailable')
            .condition('partyId', partyId).condition(cf.makeConditionDate('fromDate', 'thruDate', null)).count() > 0
            || ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortTypeEnumId', 'WetAvailable').condition('ownerPartyId', partyId).count() > 0
    let hours = null
    if (hasAvailable) hours = intervalsOf({partyId: partyId, workEffortTypeEnumIds: ['WetAvailable']}, () => 'available')
            .map((interval) => ({fromMs: interval.fromMs, thruMs: interval.thruMs}))
    else if (workingHoursOnly) hours = defaultHours()
    if (hours) { entry.workingHourList = asDates(hours); if (workingHoursOnly) hoursByParty.push(hours) }
    busyAll.push(...busy)
    freeBusyList.push(entry)
})
for (const facilityId of unique(facilityIdList)) attempt(`facility ${facilityId}`, () => {
    const busy = intervalsOf({facilityId: facilityId}, bookingStatus)
    busyAll.push(...busy)
    freeBusyList.push({resourceType: 'facility', facilityId: facilityId, busyList: asDates(busy)})
})
for (const assetId of unique(assetIdList)) attempt(`asset ${assetId}`, () => {
    const busy = intervalsOf({assetId: assetId}, bookingStatus)
    busyAll.push(...busy)
    freeBusyList.push({resourceType: 'asset', assetId: assetId, busyList: asDates(busy)})
})

const minutes = durationMinutes == null ? 0 : Number(durationMinutes)
if (!(minutes > 0)) return
const durationMs = minutes * 60000
const stepMs = Math.max(5, Number(slotMinutes) || 30) * 60000
const limit = Math.max(1, Number(suggestionLimit) || 10)
const nowMs = toMillis(ec.user.nowTimestamp)
for (let start = Math.ceil(Math.max(fromMs, nowMs) / stepMs) * stepMs; start + durationMs <= thruMs && suggestedSlotList.length < limit; start += stepMs) {
    const end = start + durationMs
    if (busyAll.some((busy) => busy.fromMs < end && busy.thruMs > start)) continue
    if (!hoursByParty.every((hours) => hours.some((interval) => interval.fromMs <= start && interval.thruMs >= end))) continue
    suggestedSlotList.push({fromDate: new Date(start), thruDate: new Date(end)})
}

requiresApproval = false
approverPartyIdList = []
conflictList = []
if (!facilityId === !assetId) { ec.message.addError('Book one meeting room (facilityId) or one piece of equipment (assetId)'); return }
ec.service.sync().name('mantle.work.EventServices.check#EventAccess').parameters({workEffortId: workEffortId, permission: 'edit'}).call()
if (ec.message.hasError()) return
const cf = ec.entity.conditionFactory
const toMillis = (value) => {
    if (value == null || value === '') return null
    const text = String(value)
    return /^-?\d+$/.test(text) ? Number(text) : Date.parse(text)
}
const resource = facilityId ? ec.entity.find('mantle.facility.Facility').condition('facilityId', facilityId).one()
        : ec.entity.find('mantle.product.asset.Asset').condition('assetId', assetId).one()
if (resource == null) { ec.message.addError(facilityId ? `Facility ${facilityId} not found` : `Asset ${assetId} not found`); return }
const resourceName = (facilityId ? resource.facilityName : resource.assetName) || facilityId || assetId
const now = ec.user.nowTimestamp
const nowMs = toMillis(now)
// a current booking stays as it is; a denied one is asked again
let existing = null
if (facilityId) {
    existing = ec.entity.find('mantle.work.effort.WorkEffortFacility').condition('workEffortId', workEffortId).condition('facilityId', facilityId).one()
    if (existing != null && existing.statusId && existing.statusId !== 'WefRequestDenied') { statusId = existing.statusId; requiresApproval = statusId === 'WefRequested'; return }
} else {
    const rows = Array.from(ec.entity.find('mantle.work.effort.WorkEffortAssetAssign').condition('workEffortId', workEffortId)
            .condition('assetId', assetId).list()).filter((row) => row.thruDate == null || toMillis(row.thruDate) > nowMs)
    const current = rows.find((row) => row.statusId !== 'WeaaRequestDenied')
    if (current != null) { statusId = current.statusId; requiresApproval = statusId === 'WeaaRequested'; return }
}

const span = ec.service.sync().name('mantle.work.WorkEffortServices.get#WorkEffortStartEnd').parameters({workEffortId: workEffortId}).call()
const startMs = toMillis(span?.startDate)
if (startMs == null) { ec.message.addError('Set the event\'s time before booking a room or equipment for it'); return }
const endMs = toMillis(span?.endDate) ?? startMs + 3600000
const dayText = (millis) => ec.l10n.format(String(millis), 'yyyy-MM-dd')
const events = ec.service.sync().name('mantle.work.EventServices.get#FullCalendarData').parameters({facilityId: facilityId, assetId: assetId,
    start: dayText(startMs), end: dayText(endMs), excludeCancelled: true,
    titleGString: '${workEffort.workEffortName || workEffort.workEffortId}'}).call()?.eventList || []
if (ec.message.hasError()) return
for (const event of Array.from(events)) {
    if (event.workEffortId === workEffortId || event.recurringEventId === workEffortId) continue
    const eventStart = toMillis(event.startMillis)
    const eventEnd = event.endMillis != null ? toMillis(event.endMillis) : eventStart + 3600000
    if (eventStart < endMs && eventEnd > startMs) conflictList.push({workEffortId: event.workEffortId, workEffortName: event.title,
        fromDate: new Date(eventStart), thruDate: new Date(eventEnd), bookingStatusId: event.bookingStatusId ?? null})
}
if (conflictList.length && !allowConflicts) {
    ec.message.addError(`${resourceName} is booked then: ${conflictList.map((conflict) => conflict.workEffortName).join(', ')}`); return }

// the placeholder policy: the resource's current approvers
const userPartyId = ec.user.userAccount?.partyId || null
approverPartyIdList = Array.from(new Set(Array.from((facilityId
        ? ec.entity.find('mantle.facility.FacilityParty').condition('facilityId', facilityId)
        : ec.entity.find('mantle.product.asset.AssetPartyAssignment').condition('assetId', assetId))
        .condition('roleTypeId', 'BookingApprover').condition(cf.makeConditionDate('fromDate', 'thruDate', null)).list())
        .map((row) => row.partyId)))
requiresApproval = approverPartyIdList.length > 0 && !approverPartyIdList.includes(userPartyId)
statusId = facilityId ? (requiresApproval ? 'WefRequested' : 'WefAssigned') : (requiresApproval ? 'WeaaRequested' : 'WeaaAssigned')
if (facilityId) {
