}
for (const row of ec.entity.find('mantle.work.effort.WorkEffortAssetAssign').condition('workEffortId', workEffortId).condition('assetId', assetId).list()) {
    const thruText = row.thruDate == null ? null : String(row.thruDate)
    const thruMs = thruText == null ? null : (/^-?\d+$/.test(thruText) ? Number(thruText) : Date.parse(thruText))
    if (thruMs != null && thruMs <= nowMs) continue
    row.set('thruDate', now)
    row.update()
    cancelledCount++
}

bookingList = []; conflictList = []; rerequestedCount = 0
ec.service.sync().name('mantle.work.EventServices.check#EventAccess').parameters({workEffortId: workEffortId, permission: 'edit'}).call()
if (ec.message.hasError()) return
const cf = ec.entity.conditionFactory
const toMillis = (value) => {
    if (value == null || value === '') return null
    const text = String(value)
    return /^-?\d+$/.test(text) ? Number(text) : Date.parse(text)
}
const nowMs = toMillis(ec.user.nowTimestamp)
const rooms = Array.from(ec.entity.find('mantle.work.effort.WorkEffortFacility').condition('workEffortId', workEffortId).list())
        .filter((row) => row.statusId && row.statusId !== 'WefRequestDenied')
const assets = Array.from(ec.entity.find('mantle.work.effort.WorkEffortAssetAssign').condition('workEffortId', workEffortId).list())
        .filter((row) => row.statusId !== 'WeaaRequestDenied' && (row.thruDate == null || toMillis(row.thruDate) > nowMs))
if (!rooms.length && !assets.length) return
const span = ec.service.sync().name('mantle.work.WorkEffortServices.get#WorkEffortStartEnd').parameters({workEffortId: workEffortId}).call()
const startMs = toMillis(span?.startDate)
if (startMs == null) return
const endMs = toMillis(span?.endDate) ?? startMs + 3600000
// the series the event is of, or is: its other instances are the same meeting
const link = ec.entity.find('mantle.work.effort.WorkEffortAssoc').condition('toWorkEffortId', workEffortId)
        .condition('workEffortAssocTypeEnumId', 'WeatRecurrenceInstance').list()[0] ?? null
const own = new Set([workEffortId, link?.workEffortId].filter((id) => id))
const dayText = (millis) => ec.l10n.format(String(millis), 'yyyy-MM-dd')
const userPartyId = ec.user.userAccount?.partyId || null
const changes = []
const check = (kind, row) => {
    const facilityId = kind === 'facility' ? row.facilityId : null
    const assetId = kind === 'asset' ? row.assetId : null
    const resource = facilityId ? ec.entity.find('mantle.facility.Facility').condition('facilityId', facilityId).one()
            : ec.entity.find('mantle.product.asset.Asset').condition('assetId', assetId).one()
    const resourceName = (facilityId ? resource?.facilityName : resource?.assetName) || facilityId || assetId
    const events = ec.service.sync().name('mantle.work.EventServices.get#FullCalendarData').parameters({facilityId: facilityId,
        assetId: assetId, start: dayText(startMs), end: dayText(endMs), excludeCancelled: true,
        titleGString: '${workEffort.workEffortName || workEffort.workEffortId}'}).call()?.eventList || []
    if (ec.message.hasError()) return
    const conflicts = []
    for (const event of Array.from(events)) {
        if (own.has(event.workEffortId) || own.has(event.recurringEventId)) continue
        const eventStart = toMillis(event.startMillis)
        const eventEnd = event.endMillis != null ? toMillis(event.endMillis) : eventStart + 3600000
        if (eventStart < endMs && eventEnd > startMs) conflicts.push({facilityId: facilityId, assetId: assetId, resourceName: resourceName,
            workEffortId: event.workEffortId, workEffortName: event.title, fromDate: new Date(eventStart), thruDate: new Date(eventEnd),
            bookingStatusId: event.bookingStatusId ?? null})
    }
    const approvers = Array.from(new Set(Array.from((facilityId
            ? ec.entity.find('mantle.facility.FacilityParty').condition('facilityId', facilityId)
            : ec.entity.find('mantle.product.asset.AssetPartyAssignment').condition('assetId', assetId))
            .condition('roleTypeId', 'BookingApprover').condition(cf.makeConditionDate('fromDate', 'thruDate', null)).list())
            .map((approver) => approver.partyId)))
    const needsApproval = approvers.length > 0 && !approvers.includes(userPartyId)
    const assigned = facilityId ? 'WefAssigned' : 'WeaaAssigned'
    const requested = facilityId ? 'WefRequested' : 'WeaaRequested'
    const statusId = reapprove && needsApproval && row.statusId === assigned ? requested : row.statusId
    if (statusId !== row.statusId) changes.push([row, statusId])
    bookingList.push({facilityId: facilityId, assetId: assetId, resourceName: resourceName, statusId: statusId,
        previousStatusId: row.statusId ?? null, conflictList: conflicts})
