}
for (const row of rooms) { check('facility', row); if (ec.message.hasError()) return }
for (const row of assets) { check('asset', row); if (ec.message.hasError()) return }
if (conflictList.length && !allowConflicts) {
    const byResource = new Map()
    for (const conflict of conflictList) {
        if (!byResource.has(conflict.resourceName)) byResource.set(conflict.resourceName, [])
        byResource.get(conflict.resourceName).push(conflict.workEffortName)
    }
    ec.message.addError(Array.from(byResource).map(([name, events]) => `${name} is booked then: ${events.join(', ')}`).join('; '))
    return
}
for (const [row, statusId] of changes) { row.set('statusId', statusId); row.update(); rerequestedCount++ }

reminderSeqIdList = []
removedCount = 0
const userPartyId = ec.user.userAccount?.partyId
if (!userPartyId) { ec.message.addError('Reminders need a user with a party'); return }
if (partyId && partyId !== userPartyId) { ec.message.addError('You can set only your own reminders'); return }
const cf = ec.entity.conditionFactory
const workEffort = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
const onIt = workEffort != null && (workEffort.ownerPartyId === userPartyId || ec.entity.find('mantle.work.effort.WorkEffortParty')
        .condition('workEffortId', workEffortId).condition('partyId', userPartyId).condition(cf.makeConditionDate('fromDate', 'thruDate', null)).count() > 0)
if (!onIt) { ec.message.addError(`You are not on ${workEffort?.workEffortName || workEffortId}`); return }
const wanted = []
for (const item of Array.from(reminderList || [])) {
    const offset = Number(item?.offsetMinutes)
    if (!Number.isInteger(offset) || offset < 0 || offset > 43200) {
        ec.message.addError(`A reminder is 0 to 43200 minutes (30 days) before, not ${item?.offsetMinutes}`); return }
    const method = item.methodEnumId || 'WermNotification'
    if (method !== 'WermNotification' && method !== 'WermEmail') { ec.message.addError(`Unknown reminder method ${method}`); return }
    if (!wanted.some((other) => other.offset === offset && other.method === method)) wanted.push({offset: offset, method: method})
}
const existing = Array.from(ec.entity.find('mantle.work.effort.WorkEffortReminder').condition('workEffortId', workEffortId)
        .condition('partyId', userPartyId).list())
let nextSeq = existing.reduce((max, row) => Math.max(max, Number(row.reminderSeqId) || 0), 0)
const kept = new Set()
for (const item of wanted) {
    const same = existing.find((row) => !kept.has(row.reminderSeqId) && Number(String(row.offsetMinutes)) === item.offset
            && (row.methodEnumId || 'WermNotification') === item.method)
    if (same != null) { kept.add(same.reminderSeqId); reminderSeqIdList.push(same.reminderSeqId); continue }
    nextSeq++
    const seqId = String(nextSeq).padStart(2, '0')
    ec.service.sync().name('create#mantle.work.effort.WorkEffortReminder').parameters({workEffortId: workEffortId,
        partyId: userPartyId, reminderSeqId: seqId, offsetMinutes: item.offset, methodEnumId: item.method}).call()
    if (ec.message.hasError()) return
    reminderSeqIdList.push(seqId)
}
for (const row of existing) if (!kept.has(row.reminderSeqId)) { row.delete(); removedCount++ }

sentCount = 0
failedCount = 0
const cf = ec.entity.conditionFactory
const toMillis = (value) => {
    if (value == null || value === '') return null
    if (typeof value === 'number') return value
    if (value instanceof Date) return value.getTime()
    const text = String(value)
    return /^-?\d+$/.test(text) ? Number(text) : Date.parse(text)
}
const day = 86400000
const now = ec.user.nowTimestamp
const nowMs = toMillis(now)
const windowStart = new Date(nowMs - day)
const windowEnd = new Date(nowMs + 31 * day)
const between = (field) => cf.makeCondition([cf.makeCondition(field, 'greater-equals', windowStart), cf.makeCondition(field, 'less-equals', windowEnd)], 'and')
const dayText = (millis) => new Date(millis).toISOString().substring(0, 10)
const anchorCondition = cf.makeCondition([between('estimatedStartDate'), between('actualStartDate'), between('estimatedCompletionDate'),
    cf.makeCondition([cf.makeCondition('allDayStart', 'greater-equals', ec.l10n.parseDate(dayText(nowMs - day), 'yyyy-MM-dd')),
        cf.makeCondition('allDayStart', 'less-equals', ec.l10n.parseDate(dayText(nowMs + 31 * day), 'yyyy-MM-dd'))], 'and'),
    cf.makeCondition('recurStartCron', 'is-not-null', null), cf.makeCondition('rrule', 'is-not-null', null)], 'or')
const reminders = Array.from(ec.entity.find('mantle.work.effort.WorkEffortReminderDetail')
        .condition(cf.makeCondition('workEffortTypeEnumId', 'in', ['WetEvent', 'WetTask']))
        .condition(cf.makeCondition('statusId', 'not-in', ['WeCancelled', 'WeComplete', 'WeClosed'], true))
        .condition(anchorCondition).list())
if (!reminders.length) return
// the events' instances in the window, once each
const eventIds = Array.from(new Set(reminders.filter((row) => row.workEffortTypeEnumId !== 'WetTask').map((row) => row.workEffortId)))
const instancesById = new Map()
if (eventIds.length) {
    const rows = Array.from(ec.entity.find('mantle.work.effort.WorkEffort').condition(cf.makeCondition('workEffortId', 'in', eventIds)).list())
    const out = ec.service.sync().name('mantle.work.EventServices.get#EventInstances').parameters({workEffortList: rows.map((row) => row.getMap()),
        rangeStart: windowStart, rangeEnd: windowEnd}).call()
    if (ec.message.hasError()) return
    for (const instance of Array.from(out?.instanceList || [])) {
        // a series' reminders are of all its instances, those changed on their own too
        for (const key of new Set([instance.seriesWorkEffortId || instance.workEffortId, instance.workEffortId])) {
            if (!instancesById.has(key)) instancesById.set(key, [])
            instancesById.get(key).push(instance)
        }
    }
}
for (const reminder of reminders) {
    const offsetMs = (Number(String(reminder.offsetMinutes ?? 0)) || 0) * 60000
    const sentMs = toMillis(reminder.sentDate)
    const snoozedMs = toMillis(reminder.snoozedThruDate)
    if (snoozedMs != null && snoozedMs > nowMs) continue
    let anchors
    if (reminder.workEffortTypeEnumId === 'WetTask') {
        const due = toMillis(reminder.estimatedCompletionDate || reminder.estimatedStartDate)
        anchors = due == null || due < nowMs - day ? [] : [{start: due, end: null}]
    } else {
        anchors = (instancesById.get(reminder.workEffortId) || []).filter((instance) => (instance.end ?? instance.start) > nowMs)
                .map((instance) => ({start: instance.start, end: instance.end}))
    }
    // the latest instance whose reminder time has come and that was not reminded of yet (a snooze that ran out
    // reminds again of the instance it was about)
    const due = anchors.filter((anchor) => anchor.start - offsetMs <= nowMs
            && (snoozedMs != null || sentMs == null || anchor.start - offsetMs > sentMs)).sort((a, b) => b.start - a.start)[0]
    if (!due) continue
    try {
        ec.service.sync().name('mantle.work.EventServices.send#WorkEffortReminder').parameters({workEffortId: reminder.workEffortId,
            partyId: reminder.partyId, reminderSeqId: reminder.reminderSeqId, instanceStart: new Date(due.start)})
                .requireNewTransaction(true).call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
        sentCount++
    } catch (err) {
        failedCount++
        ec.logger.error(`Reminder ${reminder.reminderSeqId} of ${reminder.workEffortId} for party ${reminder.partyId} not sent: ${err && err.message ? err.message : err}`)
        ec.message.clearErrors()
    }
}

method = 'none'
const reminder = ec.entity.find('mantle.work.effort.WorkEffortReminder').condition('workEffortId', workEffortId)
        .condition('partyId', partyId).condition('reminderSeqId', reminderSeqId).one()
if (reminder == null) return
const workEffort = ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).one()
const toMillis = (value) => {
    if (value == null || value === '') return null
    const text = String(value)
    return /^-?\d+$/.test(text) ? Number(text) : Date.parse(text)
}
const startMs = toMillis(instanceStart)
const minutes = Math.round((startMs - toMillis(ec.user.nowTimestamp)) / 60000)
const isTask = workEffort.workEffortTypeEnumId === 'WetTask'
const plural = (count, unit) => `${count} ${unit}${count === 1 ? '' : 's'}`
const relative = minutes <= 0 ? 'now' : minutes < 60 ? `in ${plural(minutes, 'minute')}` : minutes < 1440
        ? `in ${plural(Math.round(minutes / 60), 'hour')}` : `in ${plural(Math.round(minutes / 1440), 'day')}`
const whenText = isTask ? `due ${relative}` : (minutes <= 0 ? 'starting now' : `starts ${relative}`)
const name = workEffort.workEffortName || workEffortId
const userIds = Array.from(ec.entity.find('moqui.security.UserAccount').condition('partyId', partyId).selectField('userId')
        .disableAuthz().list()).map((account) => account.userId)
if (reminder.methodEnumId !== 'WermEmail' && userIds.length) {
    const nm = ec.makeNotificationMessage().topic('WorkEffortReminder').userIds(userIds).message({workEffortId: workEffortId,
        workEffortName: name, whenText: whenText, startDate: startMs, reminderSeqId: reminderSeqId,
        recordEntityName: 'mantle.work.effort.WorkEffort', recordId: workEffortId})
    if (typeof nm.reasonEnumId === 'function') nm.reasonEnumId('NrReminder')
    if (typeof nm.recordEntityName === 'function') nm.record('mantle.work.effort.WorkEffort', workEffortId)
    nm.send()
    method = 'notification'
} else {
    const toAddress = ec.service.sync().name('mantle.party.ContactServices.get#PrimaryEmailAddress').parameters({partyId: partyId}).call()?.emailAddress
    const fromAddress = System.getProperty('mantle.calendar.email.from') || (workEffort.ownerPartyId ? ec.service.sync()
            .name('mantle.party.ContactServices.get#PrimaryEmailAddress').parameters({partyId: workEffort.ownerPartyId}).call()?.emailAddress : null)
    if (toAddress && fromAddress) {
        const subject = `Reminder: ${name}, ${whenText}`
        const when = ec.l10n.format(String(startMs), 'EEE, MMM d, yyyy h:mm a z')
        ec.service.sync().name('org.moqui.impl.EmailServices.send#EmailTemplate').parameters({emailTemplateId: 'MANTLE_CALENDAR_EMAIL',
            toAddresses: toAddress, bodyParameters: {subject: subject, fromAddress: fromAddress, fromName: 'Reminder'},
            body: `<html><body><p>${String(subject).replace(/[<>&]/g, (ch) => ({'<': '&lt;', '>': '&gt;', '&': '&amp;'})[ch])}</p><p>${when}</p></body></html>`,
            bodyText: `${subject}\n${when}`}).call()
        if (ec.message.hasError()) return
        method = 'email'
    } else {
        ec.logger.warn(`Reminder ${reminderSeqId} of ${workEffortId} for party ${partyId}: ${toAddress ? 'no address to send from (mantle.calendar.email.from)' : 'no user and no email address'}`)
    }
}
reminder.set('sentDate', ec.user.nowTimestamp)
reminder.set('snoozedThruDate', null)
reminder.update()

updatedCount = 0
const partyId = ec.user.userAccount?.partyId
if (!partyId) { ec.message.addError('Snoozing a reminder needs a user with a party'); return }
let find = ec.entity.find('mantle.work.effort.WorkEffortReminder').condition('workEffortId', workEffortId).condition('partyId', partyId)
if (reminderSeqId) find = find.condition('reminderSeqId', reminderSeqId)
const rows = Array.from(find.list())
if (!rows.length) { ec.message.addError(`You have no reminder of ${workEffortId}`); return }
const nowText = String(ec.user.nowTimestamp)
const nowMs = /^-?\d+$/.test(nowText) ? Number(nowText) : Date.parse(nowText)
const thruText = snoozedThruDate == null ? null : String(snoozedThruDate)
const thruMs = thruText ? (/^-?\d+$/.test(thruText) ? Number(thruText) : Date.parse(thruText))
        : nowMs + Math.max(1, Number(snoozeMinutes) || 10) * 60000
snoozedThruDate = new Date(thruMs)
for (const row of rows) { row.set('snoozedThruDate', snoozedThruDate); row.update(); updatedCount++ }

// A Date reaches a script as epoch millis text (UTC midnight) or yyyy-MM-dd text; steps are UTC days on dates
const startText = String(startDate)
let nextDay
if (/^-?\d+$/.test(startText)) {
    const at = new Date(Number(startText))
    nextDay = new Date(Date.UTC(at.getUTCFullYear(), at.getUTCMonth(), at.getUTCDate() + 1))
} else {
    const [y, m, d] = startText.slice(0, 10).split('-').map(Number)
    nextDay = new Date(Date.UTC(y, m - 1, d + 1))
}
calendarDays = 1
skipWeekends = 0
skipHolidays = 0
// getUTCDay: 0 is Sunday and 6 is Saturday
if (skipSaturday && nextDay.getUTCDay() === 6) {
    nextDay = new Date(Date.UTC(nextDay.getUTCFullYear(), nextDay.getUTCMonth(), nextDay.getUTCDate() + 1))
    calendarDays += 1
    skipWeekends += 1
}
if (skipSunday && nextDay.getUTCDay() === 0) {
    nextDay = new Date(Date.UTC(nextDay.getUTCFullYear(), nextDay.getUTCMonth(), nextDay.getUTCDate() + 1))
    calendarDays += 1
    skipWeekends += 1
}
nextDayDate = nextDay.toISOString().slice(0, 10)

futureDayDate = startDate
calendarDays = 0
skipWeekends = 0
skipHolidays = 0
for (let i = Number(businessDays); i > 0; i--) {
    const nextOut = ec.service.sync().name("mantle.work.EventServices.get#NextBusinessDay")
            .parameters(Object.assign({}, context, {startDate:futureDayDate})).call()
    futureDayDate = nextOut.nextDayDate
    calendarDays += nextOut.calendarDays
    skipWeekends += nextOut.skipWeekends
    skipHolidays += nextOut.skipHolidays
    // ec.logger.warn(`business days left ${i-1} futureDayDate ${futureDayDate} calendarDays ${calendarDays} skipWeekends ${skipWeekends} skipHolidays ${skipHolidays}`)
}
